/* 3.5 — transpose: rows become columns; and for a rotation, R.T undoes R */
W.w_transpose = function (box) {
  V.say(box, '<b>הזז את המחוון</b> כדי לראות את השחלוף כ"היפוך סביב האלכסון": כל איבר ' + ENG('A[i, j]') + ' עובר ל־' + ENG('A.T[j, i]') + '. ולמטה — תכונה שתחזור בפרק 3.6: לסיבוב, ' + ENG('R.T') + ' מבטל את ' + ENG('R') + '. <b>סובב את התמונה ואז לחץ על "הפעל R.T"</b>.');
  let t = 0, th = 35, back = false; const r = row(box); V.slider(r, 'שחלוף', 0, 1, 0.01, t, v => { t = v; draw(); }, v => F(v, 2)); const cv = D4.canvas(box, 700, 230, 700);
  const A = [[1, 2, 3], [4, 5, 6]]; const m = mono(box);
  box.appendChild(el('h4', { text: 'סיבוב: R.T = R⁻¹' })); const r2 = row(box); V.slider(r2, 'θ', -90, 90, 1, th, v => { th = v; back = false; draw(); }); V.btns(r2, [['הפעל R.T', () => { back = !back; draw(); }, 'primary']]);
  const I = IMG(); const fx = flex(box); const a = K0.cv(colm(fx, 'R @ img'), 200, 130, 280), b = K0.cv(colm(fx, 'R.T @ R @ img'), 200, 130, 280); const m2 = mono(box);
  function draw() { const x = cv.getContext('2d'); x.clearRect(0, 0, 700, 230); const C = 46, O = [270, 30]; x.strokeStyle = '#ced4da'; x.setLineDash([4, 4]); x.beginPath(); x.moveTo(O[0], O[1]); x.lineTo(O[0] + 3 * C, O[1] + 3 * C); x.stroke(); x.setLineDash([]);
    A.forEach((rw, i) => rw.forEach((v, j) => { const X = O[0] + (j * (1 - t) + i * t) * C, Y = O[1] + (i * (1 - t) + j * t) * C; x.fillStyle = ['#d0ebff', '#d3f9d8'][i]; x.fillRect(X, Y, C - 4, C - 4); D4.txt(x, String(v), X + C / 2 - 2, Y + C / 2 + 4, '#212529', 15, 'center', true); }));
    D4.txt(x, t < 0.5 ? 'A — (2, 3)' : 'A.T — (3, 2)', 120, 60, '#495057', 13, 'center', true);
    m.textContent = 'A   = [[1, 2, 3],\n       [4, 5, 6]]          # shape (2, 3)\nA.T = [[1, 4],\n       [2, 5],\n       [3, 6]]             # shape (3, 2): row i of A is column i of A.T\n# (A @ B).T == B.T @ A.T    — the order flips';
    const R = M2.rot(th * Math.PI / 180); K0.show(a, K0.warp(I, R), 200, 130, 3); K0.show(b, back ? K0.warp(I, M2.mul(M2.T(R), R)) : K0.warp(I, R), 200, 130, 3); const P = M2.mul(M2.T(R), R); m2.textContent = 'R     = ' + ms(R) + '\nR.T   = ' + ms(M2.T(R)) + '\nR.T @ R = ' + ms(P) + (back ? '      # the identity: R.T undid R' : '      # press the button'); }
  draw();
};

/* 3.6 — inverse: why warping pulls from the source (no holes), and what a singular matrix destroys */
W.w_inverse = function (box) {
  V.say(box, 'איך מסובבים תמונה? <b>בחר שיטה</b>. "דחיפה": עוברים על כל פיקסל <i>במקור</i> ושולחים אותו ליעד עם ' + ENG('A') + ' — ונשארים חורים. "משיכה": עוברים על כל פיקסל <i>ביעד</i> ושואלים "מאיפה באתי?" עם ' + ENG('A⁻¹') + ' — אין חורים. ובלשונית השלישית: מטריצה בלי הפוכה.');
  const I = IMG(); let mode = 0, th = 25, sc = 1.2; V.tabs(box, ['דחיפה — A על כל פיקסל מקור', 'משיכה — A⁻¹ על כל פיקסל יעד', 'מטריצה סינגולרית'], i => { mode = i; draw(); }, 0);
  const r = row(box); V.slider(r, 'θ', -60, 60, 1, th, v => { th = v; draw(); }); V.slider(r, 'הגדלה', 0.6, 2.5, 0.05, sc, v => { sc = v; draw(); }, v => F(v, 2));
  const fx = flex(box); const a = K0.cv(colm(fx, 'img'), 200, 130, 300), b = K0.cv(colm(fx, 'התוצאה'), 200, 130, 300); const m = mono(box); const out = V.say(box);
  function draw() { const R = M2.rot(th * Math.PI / 180), A = mode === 2 ? [[1, 2], [0.5, 1]] : M2.mul([[sc, 0], [0, sc]], R); K0.show(a, I.d, 200, 130, 3); let O, holes = 0;
    if (mode === 0) { O = new Uint8ClampedArray(200 * 130 * 3).fill(235); const hit = new Uint8Array(200 * 130); for (let y = 0; y < 130; y++) for (let x = 0; x < 200; x++) { const u = x + 0.5 - 100, v = 65 - (y + 0.5); const q = M2.app(A, [u, v]); const X = Math.floor(100 + q[0]), Y = Math.floor(65 - q[1]); if (X < 0 || Y < 0 || X >= 200 || Y >= 130) continue; hit[Y * 200 + X] = 1; for (let c = 0; c < 3; c++) O[3 * (Y * 200 + X) + c] = I.d[3 * (y * 200 + x) + c]; }
      const Ai = M2.inv(A); for (let y = 0; y < 130; y++) for (let x = 0; x < 200; x++) { if (hit[y * 200 + x]) continue; const s = M2.app(Ai, [x + 0.5 - 100, 65 - (y + 0.5)]); if (Math.abs(s[0]) < 99 && Math.abs(s[1]) < 64) { holes++; O[3 * (y * 200 + x)] = 255; O[3 * (y * 200 + x) + 1] = 0; O[3 * (y * 200 + x) + 2] = 255; } } }
    else O = K0.warp(I, A); K0.show(b, O, 200, 130, 3);
    const Ai = M2.inv(A); m.textContent = mode === 0 ? '# push: for every SOURCE pixel p:   out[A @ p] = img[p]\nA = ' + ms(A) + '      det = ' + F(M2.det(A), 3) : mode === 1 ? '# pull: for every DESTINATION pixel q:   out[q] = img[A_inv @ q]   (bilinear between neighbours)\nA     = ' + ms(A) + '\nA_inv = ' + ms(Ai) + '      # np.linalg.inv(A);  for a rotation alone: R.T' : 'A = np.array([[1, 2], [0.5, 1]])     # columns (1, 0.5) and (2, 1): the same direction\nnp.linalg.det(A) -> ' + F(M2.det(A), 3) + '\nnp.linalg.inv(A) -> LinAlgError: Singular matrix';
    out.innerHTML = mode === 0 ? (holes ? badge(false, holes + ' פיקסלים ביעד לא קיבלו אף ערך (בסגול).') : 'כאן לא נשארו חורים — הגדל את התמונה או סובב.') + ' כשמגדילים, לכל פיקסל מקור יש יותר מפיקסל יעד אחד שצריך למלא; כשמסובבים, נקודות נופלות בין תאי הרשת. לכן אף ספרייה לא עובדת כך.' : mode === 1 ? badge(true, 'בלי חורים') + ' — כל פיקסל ביעד שאל "מאיפה באתי?" וקיבל תשובה (ממוצע של ארבעת השכנים). זה מה ש־' + ENG('cv2.warpAffine') + ' עושה במודול 1 — ולכן היא צריכה את ההפוכה, או מחשבת אותה בעצמה.' : 'שתי העמודות על אותו קו — כל המישור נמחץ לקו אחד, וכל התמונה הופכת לפסים. מידע אבד: נקודות שונות נחתו באותו מקום, ואין דרך לדעת מאיפה כל אחת הגיעה. אין הפוכה.'; }
  draw();
};

/* 3.7 — the determinant: how much area grows, and when it flips or collapses */
