  let c1 = [2, 0], c2 = [0, 0.5]; const r = row(box); V.btns(r, [['S (הגדלה)', () => set([2, 0], [0, 0.5])], ['סיבוב 30°', () => set([0.87, 0.5], [-0.5, 0.87])], ['שיקוף', () => set([-1, 0], [0, 1])], ['H (גזירה)', () => set([1, 0], [0.5, 1])], ['A של הקוד', () => set([2, 1], [1, 3])]]);
  function set(a, b) { c1 = a; c2 = b; draw(); }
  const P = K0.plane(box, { w: 520, h: 360, s: 50, ox: 220, oy: 230 }); const m = mono(box); const out = V.say(box);
  P.drag(() => [c1, c2], (i, q) => { q = q.map(z => Math.round(z * 4) / 4); i ? c2 = q : c1 = q; draw(); });
  function draw() { P.grid(); const x = P.x, d = c1[0] * c2[1] - c2[0] * c1[1]; x.fillStyle = Math.abs(d) < 1e-9 ? 'rgba(134,142,150,.4)' : d > 0 ? 'rgba(28,126,214,.18)' : 'rgba(224,49,49,.2)'; x.beginPath(); x.moveTo(P.X(0), P.Y(0)); x.lineTo(P.X(c1[0]), P.Y(c1[1])); x.lineTo(P.X(c1[0] + c2[0]), P.Y(c1[1] + c2[1])); x.lineTo(P.X(c2[0]), P.Y(c2[1])); x.closePath(); x.fill();
    x.strokeStyle = '#adb5bd'; x.setLineDash([3, 3]); x.strokeRect(P.X(0), P.Y(1), P.s, P.s); x.setLineDash([]); P.arrow([0, 0], c1, '#1c7ed6', 3, 'col1'); P.arrow([0, 0], c2, '#2f9e44', 3, 'col2');
    m.textContent = 'A = [[' + F(c1[0], 2) + ', ' + F(c2[0], 2) + '],\n     [' + F(c1[1], 2) + ', ' + F(c2[1], 2) + ']]\ndet = a*d - b*c = ' + F(c1[0], 2) + '*' + F(c2[1], 2) + ' - ' + F(c2[0], 2) + '*' + F(c1[1], 2) + ' = ' + F(d, 3);
    const allNZ = [c1[0], c1[1], c2[0], c2[1]].every(v => Math.abs(v) > 1e-9); out.innerHTML = Math.abs(d) < 1e-9 ? (allNZ ? badge(true, 'מצאת: דטרמיננטה 0 בלי אף אפס.') + ' העמודות פרופורציונליות — אחת היא כפולה של השנייה. ' : '<b>דטרמיננטה 0</b> — ') + 'המישור נמחץ לקו (או לנקודה), ואין הפוכה (3.6).' : d < 0 ? '<b>שלילית (' + F(d, 2) + ')</b> — השטח גדל פי ' + F(-d, 2) + ', והמרחב "התהפך": col2 נמצא עכשיו עם כיוון השעון מ־col1, כמו בשיקוף.' : 'השטח גדל פי <b>' + F(d, 2) + '</b>' + (Math.abs(d - 1) < 0.02 ? ' — כלומר לא השתנה (סיבוב, גזירה, או ההגדלה S).' : '.'); }
