    const Hs = [M3.I(), M3.T(-c[0], -c[1]), M3.mul(Ry(th), M3.T(-c[0], -c[1])), M3.mul(M3.mul(M3.T(c[0], c[1]), Ry(th)), M3.T(-c[0], -c[1]))]; const H = step === 9 ? Ry(th) : Hs[step];
    const x = K0.show(cv, K0.warpH(I, H, I.w, I.h), I.w, I.h, 3); const cc = M3.app(H, [c[0], c[1], 1]); x.fillStyle = '#1c7ed6'; x.beginPath(); x.arc(cc[0], cc[1], 4, 0, 7); x.fill(); x.fillStyle = '#e03131'; x.beginPath(); x.arc(2, 2, 4, 0, 7); x.fill();
    m.textContent = 'c = (' + c[0] + ', ' + c[1] + ')       # the image center (in this padded canvas)\nM = ' + ['I', 'T(-c)', 'Rot(' + th + ') @ T(-c)', 'T(c) @ Rot(' + th + ') @ T(-c)'][step === 9 ? 0 : step].replace('I', step === 9 ? 'Rot(' + th + ')' : 'I') + '\nM = ' + ms3(H) + '\nM @ [' + c[0] + ', ' + c[1] + ', 1] -> [' + cc.map(v => F(v, 1)).join(', ') + ']';
