  const fx = flex(box); const P = K0.plane(colm(fx, 'שתי המשוואות כקווים'), { w: 360, h: 320, s: 28, ox: 120, oy: 220 }); const Q = K0.plane(colm(fx, 'b כצירוף של העמודות'), { w: 300, h: 320, s: 14, ox: 100, oy: 240 }); const m = mono(box); const out = V.say(box);
  function line(Pl, a, c, col) { const x = Pl.x; x.strokeStyle = col; x.lineWidth = 2; x.beginPath(); const pts = []; for (const u of [-20, 20]) if (Math.abs(a[1]) > 1e-9) pts.push([u, (c - a[0] * u) / a[1]]); if (Math.abs(a[1]) <= 1e-9 && Math.abs(a[0]) > 1e-9) { pts.push([c / a[0], -20]); pts.push([c / a[0], 20]); } if (pts.length === 2) { x.moveTo(Pl.X(pts[0][0]), Pl.Y(pts[0][1])); x.lineTo(Pl.X(pts[1][0]), Pl.Y(pts[1][1])); x.stroke(); } }
