  const A = [[1.5, 1], [0.3, 1.2]]; let st = 3; const r = row(box); [[0, 0], [0, 1], [1, 0], [1, 1]].forEach(([i, j]) => V.slider(r, 'A[' + i + ', ' + j + ']', -2, 2, 0.05, A[i][j], v => { A[i][j] = v; draw(); }, v => F(v, 2))); const r2 = row(box); V.slider(r2, 'שלב', 0, 3, 0.01, st, v => { st = v; draw(); }, v => ['מעגל', 'Vᵀ', 'Σ Vᵀ', 'U Σ Vᵀ = A'][Math.round(v)]);
  const P = K0.plane(box, { w: 520, h: 360, s: 70, ox: 260, oy: 180 }); const m = mono(box);
  function svd2(A) { const AtA = [[A[0][0] ** 2 + A[1][0] ** 2, A[0][0] * A[0][1] + A[1][0] * A[1][1]], [0, A[0][1] ** 2 + A[1][1] ** 2]]; AtA[1][0] = AtA[0][1]; const E = K0.eigSym(AtA); const s = E.vals.map(v => Math.sqrt(Math.max(0, v))); let Vm = [[E.vecs[0][0], E.vecs[0][1]], [E.vecs[1][0], E.vecs[1][1]]]; if (M2.det(Vm) < 0) Vm = [[Vm[0][0], -Vm[0][1]], [Vm[1][0], -Vm[1][1]]]; const u1 = s[0] > 1e-9 ? V2.mul(1 / s[0], M2.app(A, [Vm[0][0], Vm[1][0]])) : [1, 0]; let u2 = s[1] > 1e-9 ? V2.mul(1 / s[1], M2.app(A, [Vm[0][1], Vm[1][1]])) : [-u1[1], u1[0]]; return { U: [[u1[0], u2[0]], [u1[1], u2[1]]], s, V: Vm }; }
