    P.grid(); const x = P.x; x.strokeStyle = '#ced4da'; x.beginPath(); for (let i = 0; i <= 64; i++) { const a = i * Math.PI / 32; i ? x.lineTo(P.X(Math.cos(a)), P.Y(Math.sin(a))) : x.moveTo(P.X(1), P.Y(0)); } x.stroke(); x.strokeStyle = '#1c7ed6'; x.lineWidth = 2; x.beginPath(); for (let i = 0; i <= 64; i++) { const a = i * Math.PI / 32, q = M2.app(Mx, [Math.cos(a), Math.sin(a)]); i ? x.lineTo(P.X(q[0]), P.Y(q[1])) : x.moveTo(P.X(q[0]), P.Y(q[1])); } x.stroke(); x.lineWidth = 1;
    P.arrow([0, 0], M2.app(Mx, [D.V[0][0], D.V[1][0]]), '#e8590c', 3, 'v1'); P.arrow([0, 0], M2.app(Mx, [D.V[0][1], D.V[1][1]]), '#2f9e44', 3, 'v2');
