  P.axes = () => { const x = P.x; x.clearRect(0, 0, o.w, o.h); x.strokeStyle = '#f1f3f5'; for (let u = Math.ceil(o.x0); u <= o.x1; u++) { x.beginPath(); x.moveTo(P.X(u), 0); x.lineTo(P.X(u), o.h); x.stroke(); } const st = (o.y1 - o.y0) > 30 ? 5 : (o.y1 - o.y0) > 8 ? 2 : 0.5; for (let v = Math.ceil(o.y0 / st) * st; v <= o.y1; v += st) { x.beginPath(); x.moveTo(0, P.Y(v)); x.lineTo(o.w, P.Y(v)); x.stroke(); } x.strokeStyle = '#adb5bd'; x.beginPath(); x.moveTo(0, P.Y(0)); x.lineTo(o.w, P.Y(0)); x.moveTo(P.X(0), 0); x.lineTo(P.X(0), o.h); x.stroke(); for (let u = Math.ceil(o.x0); u <= o.x1; u++) D4.txt(x, String(u), P.X(u), P.Y(0) + 12, '#adb5bd', 9, 'center'); };
  P.curve = (f, col, lw, dash) => { const x = P.x; x.strokeStyle = col; x.lineWidth = lw || 2; if (dash) x.setLineDash(dash); x.beginPath(); let pen = false; for (let i = 0; i <= o.w; i += 2) { const u = P.ux(i), v = f(u); if (!isFinite(v) || Math.abs(v) > 1e6) { pen = false; continue; } pen ? x.lineTo(i, P.Y(v)) : x.moveTo(i, P.Y(v)); pen = true; } x.stroke(); x.setLineDash([]); x.lineWidth = 1; };
