  const K = { a: 0, b: 3, c: 2, d: 7, e: 0 }; let x0 = 1; const r = row(box); Object.keys(K).forEach(n => V.slider(r, n, -4, n === 'd' ? 10 : 4, 0.5, K[n], v => { K[n] = v; draw(); }, v => F(v, 1)));
