    const fs = (term(K.a, 'x³') + term(K.b, 'x²') + term(K.c, 'x') + term(K.d, '') + term(K.e, 'eˣ')).replace(/^ \+ /, '').replace(/^ − /, '−') || '0'; const ds = (term(3 * K.a, 'x²') + term(2 * K.b, 'x') + term(K.c, '') + term(K.e, 'eˣ')).replace(/^ \+ /, '').replace(/^ − /, '−') || '0'; const num = (f(x0 + 1e-5) - f(x0 - 1e-5)) / 2e-5;
