/* =============================================================== chapter 9 */
/* a small plot with chosen ticks (fplot draws one line per integer, too many for 0..255) */
K0.ax = function (parent, o) { o = Object.assign({ w: 520, h: 240, x0: 0, x1: 1, y0: 0, y1: 1, xt: null, pad: 22 }, o); const cv = D4.canvas(parent, o.w, o.h); const x = cv.getContext('2d'); const P = { cv, x, o };
  P.X = u => o.pad + (u - o.x0) / (o.x1 - o.x0) * (o.w - 2 * o.pad); P.Y = v => o.h - o.pad - (v - o.y0) / (o.y1 - o.y0) * (o.h - 2 * o.pad); P.ux = X => o.x0 + (X - o.pad) / (o.w - 2 * o.pad) * (o.x1 - o.x0);
  P.clear = () => { x.clearRect(0, 0, o.w, o.h); x.strokeStyle = '#adb5bd'; x.beginPath(); x.moveTo(o.pad, P.Y(o.y0)); x.lineTo(o.w - o.pad, P.Y(o.y0)); x.stroke(); (o.xt || []).forEach(t => { x.strokeStyle = '#f1f3f5'; x.beginPath(); x.moveTo(P.X(t), o.pad / 2); x.lineTo(P.X(t), P.Y(o.y0)); x.stroke(); D4.txt(x, String(t), P.X(t), o.h - o.pad + 13, '#868e96', 10, 'center'); }); };
  P.bars = (edges, vals, col) => { x.fillStyle = col; vals.forEach((v, i) => { const a = P.X(edges[i]), b = P.X(edges[i + 1]); x.fillRect(a + 0.5, P.Y(v), Math.max(1, b - a - 1), P.Y(o.y0) - P.Y(v)); }); };
  P.curve = (f, col, lw, dash) => { x.strokeStyle = col; x.lineWidth = lw || 2; if (dash) x.setLineDash(dash); x.beginPath(); for (let i = 0; i <= 200; i++) { const u = o.x0 + i / 200 * (o.x1 - o.x0), v = Math.min(o.y1 * 1.2, f(u)); i ? x.lineTo(P.X(u), P.Y(v)) : x.moveTo(P.X(u), P.Y(v)); } x.stroke(); x.setLineDash([]); x.lineWidth = 1; };
  P.vline = (u, col, lab) => { x.strokeStyle = col; x.lineWidth = 2; x.beginPath(); x.moveTo(P.X(u), o.pad / 2); x.lineTo(P.X(u), P.Y(o.y0)); x.stroke(); x.lineWidth = 1; if (lab) D4.txt(x, lab, P.X(u) + 3, o.pad / 2 + 10, col, 10); };
  P.shade = (a, b, f, col) => { x.fillStyle = col; x.beginPath(); x.moveTo(P.X(a), P.Y(o.y0)); for (let i = 0; i <= 80; i++) { const u = a + i / 80 * (b - a); x.lineTo(P.X(u), P.Y(Math.min(o.y1 * 1.2, f(u)))); } x.lineTo(P.X(b), P.Y(o.y0)); x.fill(); };
  P.clear(); return P; };
K0.hist = (vals, x0, x1, nb) => { const c = new Array(nb).fill(0); vals.forEach(v => { const k = Math.floor((v - x0) / (x1 - x0) * nb); if (k >= 0 && k < nb) c[k]++; }); const e = [...Array(nb + 1)].map((_, i) => x0 + i * (x1 - x0) / nb); return { c, e, bw: (x1 - x0) / nb }; };
K0.erf = z => { const s = Math.sign(z); z = Math.abs(z); const t = 1 / (1 + 0.3275911 * z); const y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-z * z); return s * y; };
K0.Phi = z => 0.5 * (1 + K0.erf(z / Math.SQRT2));
K0.npdf = (u, m, s) => Math.exp(-0.5 * ((u - m) / s) ** 2) / (s * Math.sqrt(2 * Math.PI));

/* 9.1 — random variables: discrete (dice, a classifier's output) and continuous (pixel noise) */
