    const P = K0.ax(body, { w: 600, h: 240, x0: 0.5, x1: 30.5, y0: 0, y1: 0.2 }); const tb = el('div'); body.appendChild(tb); const m = mono(body);
    function roll(n) { for (let i = 0; i < n; i++) { let s = 0; for (let j = 0; j < k; j++) s += 1 + Math.floor(rr() * 6); rolls.push(s); } draw(); }
    function theory() { let p = [1]; for (let j = 0; j < k; j++) { const q = new Array(p.length + 6).fill(0); p.forEach((v, i) => { for (let f = 1; f <= 6; f++) q[i + f] += v / 6; }); p = q; } return p; }
    function draw() { const th = theory(); const mx = k, Mx = 6 * k; P.o.x0 = mx - 0.5; P.o.x1 = Mx + 0.5; P.o.y1 = Math.max(...th) * 1.35; P.o.xt = [...Array(Mx - mx + 1)].map((_, i) => mx + i).filter(v => k < 3 || v % k === 0 || v === mx); P.clear(); const n = rolls.length; const cnt = {}; rolls.forEach(s => cnt[s] = (cnt[s] || 0) + 1);
      const ed = [], vs = []; for (let s = mx; s <= Mx; s++) { ed.push(s - 0.4); vs.push(n ? (cnt[s] || 0) / n : 0); } ed.push(Mx + 0.6); vs.forEach((v, i) => P.bars([ed[i], ed[i] + 0.8], [v], '#ffa94d')); const x = P.x; x.strokeStyle = '#1c7ed6'; x.lineWidth = 2; x.beginPath(); for (let s = mx; s <= Mx; s++) { const X = P.X(s), Y = P.Y(th[s]); s === mx ? x.moveTo(X, Y) : x.lineTo(X, Y); } x.stroke(); x.lineWidth = 1;
      const mean = n ? rolls.reduce((a, b) => a + b, 0) / n : NaN; const mode = th.indexOf(Math.max(...th)); tb.innerHTML = table(['', 'מהטלות', 'תיאוריה'], [['מספר הטלות', n.toLocaleString(), '∞'], ['ממוצע', n ? F(mean, 3) : '—', F(3.5 * k, 1) + ' (‏3.5 × ' + k + ')'], ['הערך השכיח', n ? Object.entries(cnt).sort((a, b) => b[1] - a[1])[0][0] : '—', String(mode) + (k > 1 ? '' : ' (כולם שווים)')], ['סכום ההסתברויות', n ? '1' : '—', F(th.reduce((a, b) => a + b, 0), 3)]]);
      m.textContent = 'rolls = np.random.randint(1, 7, size=(' + Math.max(n, 1) + ', ' + k + ')).sum(axis=1)   # high is excluded: 1..6\np = np.bincount(rolls, minlength=' + (Mx + 1) + ')[' + mx + ':] / len(rolls)\n# P(sum = ' + mode + ') in theory = ' + F(th[mode], 4) + (n ? ',  measured = ' + F((cnt[mode] || 0) / n, 4) : ''); }
