    const [ma, va, sa] = st(A), [mb, vb, sb] = st(B); body.appendChild(el('div', { html: table(['', 'ממוצע', 'שונות', 'סטיית תקן', 'משקל במיזוג (1/σ²)'], [['A', F(ma, 2), F(va, 2), F(sa, 2), F(1 / va / (1 / va + 1 / vb), 2)], ['B', F(mb, 2), F(vb, 2), F(sb, 2), F(1 / vb / (1 / va + 1 / vb), 2)]]) }));
