      const rows = P.map((p, i) => { const eu = Math.hypot(p[0], p[1]); const md = Math.sqrt(p[0] * (Si[0][0] * p[0] + Si[0][1] * p[1]) + p[1] * (Si[1][0] * p[0] + Si[1][1] * p[1])); const q = toC(...p); x.fillStyle = ['#1c7ed6', '#e8590c'][i]; x.beginPath(); x.arc(q[0], q[1], 7, 0, 7); x.fill(); D4.txt(x, String.fromCharCode(65 + i), q[0], q[1] + 4, '#fff', 10, 'center'); return ['<b style="color:' + ['#1c7ed6', '#e8590c'][i] + '">מדידה ' + String.fromCharCode(65 + i) + '</b>', F(eu, 2), F(md, 2), md <= 3 ? badge(true, 'בתוך השער') : badge(false, 'מחוץ לשער')]; });
