  const stat = t => { const TP = real.filter(s => s >= t).length, FP = fake.filter(s => s >= t).length, FN = 50 - TP; return { TP, FP, FN, P: TP + FP ? TP / (TP + FP) : 1, R: TP / 50 }; };
  const grid = [...Array(101)].map((_, i) => i / 100); const pick = (ok, high) => { const c = grid.filter(t => ok(stat(t))); return c.length ? (high ? Math.max(...c) : Math.min(...c)) : th; };
